#[using="Halloc Hwx STATIC HLsegs HLscr HLtp HLlo HLhi HLst HLk HLlin HLov FSLAW FS_IN FSKEYS"] Theorem art_wrap_malloc_secL :
  forall (R : bvmap 5 word) (M : word -> option byte) (model : Model) (LB : list (Z * Z)) (FF LK : list fframe) (cr : credit) (A : list (Z * Z))
         (n rl rz qz rs qr qn m8 nd q msz : Z) (K : ShapeAlg.TSet) (Kz : list Z),
    art_ri_inv FSG MAPS0 RESV0 NOACC0 BASE BUDGET FSINV rn LB FF LK cr A M (vml_of model) -> m_halted model = None -> MInv A model ->
    getr R 10 = Z_to_bv 64 n -> 8 <= n <= 2 ^ 31 ->
    rl = AsanTab.rz_log n -> rz = 16 * 2 ^ rl -> rz = 16 * qz -> 2 <= qz <= 128 -> n = 8 * qn + m8 -> 0 <= m8 <= 7 -> rs = 8 * qr -> n <= rs <= n + 7 ->
    65536 < rs + rz ->                                                          (* [comment removed for export] *)
    nd = rs + rz + rz -> 4096 * (q - 1) < nd <= 4096 * q -> msz = 4096 * q + 4096 ->
    acredit_ok L cr n -> getr R 4 = Z_to_bv 64 (hl_tp L) -> Hoare.ret_ok (getr R 1) ->
    astack_ok L (rn_ar rn) M (hl_scr_malloc L) (U (getr R 2)) ->
    ukeyG L (rn_ar rn) 0x7a440 (mrestrict (mkH (m_vm_lazy model) A) M) (U (getr R 2)) (U (getr R 1)) (U (getr R 8)) Kz ->
    HeapIfaceAEr.HAR.amalloc_postG L (rn_ar rn) scfg (fun D => art_iface FSG MAPS0 RESV0 NOACC0 BASE BUDGET FSINV (art_rn_k rn D)) (Kz :: rn_keys rn)
         (adebit L cr n) fx R M model LB FF LK A n K ->
    srealizes ASEGS scfg (mkCfg (mkst R (0x7a19c : word) M (seg_rom ASEGS)) model) K.
Proof.
